patch.search:
        // Legacy audit route. Freeform diagnostics stay in Core.
const raw =
    String(comando || "")
        .toLowerCase()
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "");

const isExplicitRepoAuditRequest =
    /\b(audita|auditar|audit|auditoria)\b/i.test(raw) ||
    /\b(estado|mapa|resumen)\s+(del\s+)?(repo|repositorio|sistema)\b/i.test(raw);

